definition.script:
pipeline {
  agent any
  options { timestamps(); disableConcurrentBuilds() }
  parameters {
    booleanParam(name: 'SKIP_SONAR', defaultValue: true, description: 'Sonar optionnel')
    booleanParam(name: 'RUN_FRONTEND_TESTS', defaultValue: true, description: 'Karma')
    booleanParam(name: 'FORCE_FAIL', defaultValue: false, description: 'Démo FAILURE')
  }
  environment { CI = 'true' }
  stages {
    stage('Checkout') {
      steps {
        sh '''
          set -e
          cp -a /workspace/Jenkinsfile /workspace/docker-compose.yml . 2>/dev/null || true
          cp -a /workspace/backend /workspace/frontend /workspace/ml /workspace/docs /workspace/scripts .
        '''
      }
    }
    stage('Backend Build') {
      steps { dir('backend') { sh 'chmod +x mvnw && ./mvnw -B clean compile' } }
    }
    stage('Backend Tests') {
      steps { dir('backend') { sh './mvnw -B test' } }
    }
    stage('Frontend Install') {
      steps { dir('frontend') { sh 'npm ci' } }
    }
    stage('Frontend Build') {
      steps { dir('frontend') { sh 'npm run build' } }
    }
    stage('Frontend Tests') {
      when { expression { return params.RUN_FRONTEND_TESTS } }
      steps { dir('frontend') { sh 'npx ng test --watch=false --browsers=ChromeHeadlessNoSandbox' } }
    }
    stage('ML Tests') {
      steps {
        dir('ml') {
          sh '''
            set -e
            python3 -m venv .venv-ci
            . .venv-ci/bin/activate
            pip install -q -r requirements.txt
            python -m pytest -q
          '''
        }
      }
    }
    stage('ML Training') {
      steps {
        dir('ml') {
          sh '''
            set -e
            . .venv-ci/bin/activate
            python data/generate_dataset.py
            python train.py
            test -f models/recommender_model.pkl
          '''
        }
      }
    }
    stage('SonarQube (skipped)') {
      when { expression { return params.SKIP_SONAR } }
      steps { echo 'SonarQube ignoré (SKIP_SONAR=true). Aucun token lu.' }
    }
    stage('Package') {
      steps {
        dir('backend') { sh './mvnw -B -DskipTests package && ls target/*.jar' }
        sh 'test -f frontend/dist/frontend/browser/index.html'
        sh 'test -f ml/models/recommender_model.pkl'
      }
    }
    stage('Docker Build') {
      steps {
        sh '''
          set -e
          docker build -t formalearn-backend:${BUILD_NUMBER} ./backend
          docker build -t formalearn-frontend:${BUILD_NUMBER} ./frontend
          docker build -t formalearn-ml:${BUILD_NUMBER} ./ml
        '''
      }
    }
    stage('CI quality gate (demo)') {
      when { expression { return params.FORCE_FAIL } }
      steps { error('FORCE_FAIL=true : échec volontaire pour la démonstration.') }
    }
  }
  post {
    success { echo 'Pipeline SUCCESS' }
    failure { echo 'Pipeline FAILED' }
  }
}
